"use client"

import { createContext, type ReactNode, useContext, useId } from "react"
import { NumberField as NumberFieldPrimitive } from "@base-ui/react/number-field"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"
import { Label } from "@/components/ui/label"

import "@/styles/text-control.styles.css"
import "@/styles/number-field.styles.css"

//Icons
import { MinusIcon, PlusIcon } from "lucide-react"

const NumberFieldContext = createContext<{
  fieldId: string
  size: "sm" | "default" | "lg"
} | null>(null)

const numberFieldGroupVariants = cva("cn-input-control cn-number-group", {
  variants: { size: { sm: "cn-number-sm", default: "", lg: "cn-number-lg" } },
  defaultVariants: { size: "default" },
})
const numberFieldButtonVariants = cva("cn-number-stepper", {
  variants: { size: { sm: "cn-number-stepper-sm", default: "", lg: "cn-number-stepper-lg" } },
  defaultVariants: { size: "default" },
})
const numberFieldInputVariants = cva("cn-input cn-number-input", {
  variants: { size: { sm: "cn-number-input-sm", default: "", lg: "cn-number-input-lg" } },
  defaultVariants: { size: "default" },
})

function NumberField({
  id,
  className,
  size = "default",
  ...props
}: NumberFieldPrimitive.Root.Props & VariantProps<typeof numberFieldGroupVariants>) {
  const generatedId = useId()
  const fieldId = id ?? generatedId
  const sizeValue = size ?? "default"

  return (
    <NumberFieldContext.Provider value={{ fieldId, size: sizeValue }}>
      <NumberFieldPrimitive.Root
        className={cn("cn-number-field", className)}
        data-size={sizeValue}
        data-slot="number-field"
        id={fieldId}
        {...props}
      />
    </NumberFieldContext.Provider>
  )
}

function NumberFieldGroup({
  className,
  size: sizeProp,
  ...props
}: NumberFieldPrimitive.Group.Props & Partial<VariantProps<typeof numberFieldGroupVariants>>) {
  const context = useContext(NumberFieldContext)
  if (!context) {
    throw new Error("NumberFieldGroup must be used within a NumberField component.")
  }
  const size = sizeProp ?? context.size

  return (
    <NumberFieldPrimitive.Group
      className={cn(numberFieldGroupVariants({ size }), className)}
      data-slot="number-field-group"
      {...props}
    />
  )
}

function NumberFieldDecrement({
  className,
  size: sizeProp,
  children,
  ...props
}: NumberFieldPrimitive.Decrement.Props &
  Partial<VariantProps<typeof numberFieldButtonVariants>> & {
    children?: React.ReactNode
  }) {
  const context = useContext(NumberFieldContext)
  if (!context) {
    throw new Error("NumberFieldDecrement must be used within a NumberField component.")
  }
  const size = sizeProp ?? context.size

  return (
    <NumberFieldPrimitive.Decrement
      className={cn(numberFieldButtonVariants({ size }), "cn-number-decrement", className)}
      data-slot="number-field-decrement"
      tabIndex={0}
      {...props}
    >
      {children ?? <MinusIcon aria-hidden="true" />}
    </NumberFieldPrimitive.Decrement>
  )
}

function NumberFieldIncrement({
  className,
  size: sizeProp,
  children,
  ...props
}: NumberFieldPrimitive.Increment.Props &
  Partial<VariantProps<typeof numberFieldButtonVariants>> & {
    children?: ReactNode
  }) {
  const context = useContext(NumberFieldContext)
  if (!context) {
    throw new Error("NumberFieldIncrement must be used within a NumberField component.")
  }
  const size = sizeProp ?? context.size

  return (
    <NumberFieldPrimitive.Increment
      className={cn(numberFieldButtonVariants({ size }), "cn-number-increment", className)}
      data-slot="number-field-increment"
      tabIndex={0}
      {...props}
    >
      {children ?? <PlusIcon aria-hidden="true" />}
    </NumberFieldPrimitive.Increment>
  )
}

function NumberFieldInput({
  className,
  size: sizeProp,
  ...props
}: NumberFieldPrimitive.Input.Props & Partial<VariantProps<typeof numberFieldInputVariants>>) {
  const context = useContext(NumberFieldContext)
  if (!context) {
    throw new Error("NumberFieldInput must be used within a NumberField component.")
  }
  const size = sizeProp ?? context.size

  return (
    <NumberFieldPrimitive.Input
      className={cn(numberFieldInputVariants({ size }), className)}
      data-slot="number-field-input"
      {...props}
    />
  )
}

function NumberFieldScrubArea({
  className,
  label,
  ...props
}: NumberFieldPrimitive.ScrubArea.Props & {
  label: string
}) {
  const context = useContext(NumberFieldContext)
  if (!context) {
    throw new Error(
      "NumberFieldScrubArea must be used within a NumberField component for accessibility."
    )
  }

  return (
    <NumberFieldPrimitive.ScrubArea
      className={cn("cn-number-scrub", className)}
      data-slot="number-field-scrub-area"
      {...props}
    >
      <Label className="cursor-ew-resize" htmlFor={context.fieldId}>
        {label}
      </Label>
      <NumberFieldPrimitive.ScrubAreaCursor className="drop-shadow-[0_1px_1px_#0008] filter">
        <CursorGrowIcon />
      </NumberFieldPrimitive.ScrubAreaCursor>
    </NumberFieldPrimitive.ScrubArea>
  )
}

function CursorGrowIcon(props: React.ComponentProps<"svg">) {
  return (
    <svg
      fill="black"
      height="14"
      stroke="white"
      viewBox="0 0 24 14"
      width="26"
      xmlns="http://www.w3.org/2000/svg"
      {...props}
    >
      <path d="M19.5 5.5L6.49737 5.51844V2L1 6.9999L6.5 12L6.49737 8.5L19.5 8.5V12L25 6.9999L19.5 2V5.5Z" />
    </svg>
  )
}

export {
  NumberField,
  NumberFieldScrubArea,
  NumberFieldDecrement,
  NumberFieldIncrement,
  NumberFieldGroup,
  NumberFieldInput,
}

@layer components {
  .cn-number-field {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    width: 100%;
    min-width: 0;
    gap: calc(6 * var(--cn-unit));
  }
  /* Unlike text-only shells, steppers may be disabled at a boundary while the input stays enabled. */
  .cn-number-group {
    align-items: center;
    border: 1px solid var(--cn-border-control);
    background: var(--cn-surface);
    transition:
      border-color var(--cn-duration-fast) var(--cn-ease-standard),
      background-color var(--cn-duration-fast) var(--cn-ease-standard);
  }
  .cn-number-group:has(input:read-only) {
    background: var(--cn-surface-muted);
  }
  .cn-number-group:is([data-invalid], :has(input[aria-invalid="true"])):not([data-disabled]) {
    border-color: var(--cn-status-destructive-border);
  }
  .cn-number-group:has(input:focus-visible) {
    outline: 2px solid var(--cn-focus-color);
    outline-offset: 2px;
  }
  .cn-number-group[data-disabled] {
    background: var(--cn-surface-disabled);
    border-color: var(--cn-border-disabled);
    color: var(--cn-text-disabled);
  }
  .cn-number-group.cn-number-sm {
    --control-height: 32;
    --control-inset: 10;
    --control-type: 13;
    --control-leading: 18;
  }
  .cn-number-group.cn-number-lg {
    --control-height: 40;
    --control-inset: 14;
  }
  .cn-number-input {
    flex: 1;
    text-align: center;
    font-variant-numeric: tabular-nums;
  }
  .cn-number-stepper {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    align-self: stretch;
    flex-shrink: 0;
    width: calc(var(--control-height) * var(--cn-unit) - 2px);
    padding: 0;
    border: 0;
    border-radius: max(0px, calc(var(--cn-radius-control) - 1px));
    background: transparent;
    color: var(--cn-text);
    cursor: pointer;
    transition: background-color var(--cn-duration-fast) var(--cn-ease-standard);
  }
  .cn-number-stepper svg {
    width: calc(16 * var(--cn-unit));
    height: calc(16 * var(--cn-unit));
    pointer-events: none;
  }
  .cn-number-stepper:not(:disabled, [data-disabled], [data-readonly]):active {
    background: var(--cn-surface-pressed);
  }
  .cn-number-stepper:is(:disabled, [data-disabled], [data-readonly]) {
    color: var(--cn-text-disabled);
    cursor: not-allowed;
  }
  .cn-number-group[data-readonly] .cn-number-stepper {
    cursor: default;
  }
  .cn-number-stepper:focus-visible {
    outline: 2px solid var(--cn-focus-color);
    outline-offset: -3px;
    z-index: 1;
  }
  .cn-number-scrub {
    display: flex;
    cursor: ew-resize;
  }
  .cn-number-scrub:is([data-disabled], [data-readonly]) label {
    cursor: default;
  }
}
@media (hover: hover) {
  @layer components {
    .cn-number-group:not([data-disabled], [data-invalid], :has(input[aria-invalid="true"])):hover {
      border-color: var(--cn-border-hover);
    }
    .cn-number-stepper:not(:disabled, [data-disabled], [data-readonly], :active):hover {
      background: var(--cn-surface-hover);
    }
  }
}
@media (pointer: coarse) {
  @layer components {
    /* Border + 44px independent actions, with no invisible extensions. */
    .cn-number-group {
      min-height: calc(46 * var(--cn-unit));
    }
    .cn-number-group:has(> div > .cn-number-increment + .cn-number-decrement) {
      min-height: calc(94 * var(--cn-unit));
    }
    .cn-number-stepper {
      min-width: calc(44 * var(--cn-unit));
      min-height: calc(44 * var(--cn-unit));
    }
  }
}
@media (prefers-reduced-motion: reduce) {
  .cn-number-stepper,
  .cn-number-group {
    transition: none;
  }
}
@media (forced-colors: active) {
  .cn-number-stepper:focus-visible,
  .cn-number-group:has(input:focus-visible) {
    outline-color: Highlight;
  }
}
@layer components {
  .cn-number-stepper-sm {
    width: calc(30 * var(--cn-unit));
  }
  .cn-number-stepper-lg {
    width: calc(38 * var(--cn-unit));
  }
  .cn-number-input-sm {
    --control-inset: 10;
    font-size: calc(13 * var(--cn-unit));
    line-height: calc(18 * var(--cn-unit));
  }
  .cn-number-input-lg {
    --control-inset: 14;
    font-size: calc(14 * var(--cn-unit));
    line-height: calc(20 * var(--cn-unit));
  }
}

/* A disabled NumberField also owns the foreground of its composed Label. */
:where(.cn-number-field[data-disabled] label) {
  color: var(--cn-text-disabled);
}

/* Local text-entry anatomy, shared by Input, Textarea and InputGroup. */
@layer components {
  .cn-input-control,
  .cn-textarea-control,
  .cn-input-group {
    --control-height: 36;
    --control-inset: 12;
    --control-type: 14;
    --control-leading: 20;
    --textarea-min: 96;
    --textarea-block: 10;
    position: relative;
    display: inline-flex;
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    border-radius: var(--cn-radius-control);
    color: var(--cn-text);
    font-size: calc(var(--control-type) * var(--cn-unit));
    line-height: calc(var(--control-leading) * var(--cn-unit));
  }
  .cn-input-control[data-size="sm"],
  .cn-input-group:has(.cn-input-control[data-size="sm"], .cn-textarea-control[data-size="sm"]) {
    --control-height: 32;
    --control-inset: 10;
    --control-type: 13;
    --control-leading: 18;
    --textarea-min: 80;
    --textarea-block: 8;
  }
  .cn-textarea-control[data-size="sm"] {
    --control-inset: 10;
    --textarea-min: 80;
    --textarea-block: 8;
  }
  .cn-input-control[data-size="lg"],
  .cn-textarea-control[data-size="lg"],
  .cn-input-group:has(.cn-input-control[data-size="lg"], .cn-textarea-control[data-size="lg"]) {
    --control-height: 40;
    --control-inset: 14;
    --textarea-min: 112;
    --textarea-block: 12;
  }
  .cn-input-control {
    height: calc(var(--control-height) * var(--cn-unit));
  }
  .cn-text-shell,
  .cn-input-group {
    border: 1px solid var(--cn-border-control);
    background: var(--cn-surface);
    transition:
      border-color var(--cn-duration-fast) var(--cn-ease-standard),
      background-color var(--cn-duration-fast) var(--cn-ease-standard);
  }
  .cn-text-shell:has(:read-only),
  .cn-input-group:has(input:read-only, textarea:read-only) {
    background: var(--cn-surface-muted);
  }
  .cn-text-shell:has([aria-invalid="true"], [data-invalid]),
  .cn-input-group:has(
    input[aria-invalid="true"],
    textarea[aria-invalid="true"],
    input[data-invalid],
    textarea[data-invalid]
  ) {
    border-color: var(--cn-status-destructive-border);
  }
  .cn-text-shell:has(input:focus-visible, textarea:focus-visible),
  .cn-input-group:has(input:focus-visible, textarea:focus-visible) {
    outline: 2px solid var(--cn-focus-color);
    outline-offset: 2px;
  }
  .cn-text-shell:has(:disabled, [data-disabled]),
  .cn-input-group:has(input:disabled, textarea:disabled) {
    color: var(--cn-text-disabled);
    background: var(--cn-surface-disabled);
    border-color: var(--cn-border-disabled);
  }
  .cn-input,
  .cn-textarea {
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    border: 0;
    border-radius: inherit;
    background: transparent;
    color: inherit;
    font: inherit;
    outline: none;
    padding-inline: calc(var(--control-inset) * var(--cn-unit) - 1px);
  }
  .cn-input {
    height: 100%;
    padding-block: 0;
  }
  .cn-input::placeholder,
  .cn-textarea::placeholder {
    color: var(--cn-text-muted);
    opacity: 1;
  }
  .cn-input:disabled,
  .cn-textarea:disabled {
    cursor: not-allowed;
  }
  .cn-input:disabled::placeholder,
  .cn-textarea:disabled::placeholder {
    color: var(--cn-text-disabled);
  }
  .cn-textarea-control {
    min-height: calc(var(--textarea-min) * var(--cn-unit));
  }
  .cn-textarea {
    field-sizing: content;
    min-height: calc(var(--textarea-min) * var(--cn-unit) - 2px);
    padding-block: calc(var(--textarea-block) * var(--cn-unit) - 1px);
    resize: vertical;
  }
  .cn-input[type="search"]::-webkit-search-cancel-button,
  .cn-input[type="search"]::-webkit-search-decoration {
    appearance: none;
  }
  .cn-input[type="file"] {
    color: var(--cn-text-muted);
  }
  .cn-input::file-selector-button {
    margin-inline-end: calc(12 * var(--cn-unit));
    background: transparent;
    color: var(--cn-text);
    font-weight: 500;
  }
  .cn-input-group {
    align-items: center;
    min-height: calc(var(--control-height) * var(--cn-unit));
  }
  .cn-input-group > :is(.cn-input-control, .cn-textarea-control) {
    flex: 1;
    min-width: 0;
    border: 0;
    border-radius: inherit;
    background: transparent;
    outline: none;
  }
  .cn-input-group > .cn-input-control {
    height: calc(var(--control-height) * var(--cn-unit) - 2px);
  }
  .cn-input-group .cn-textarea {
    resize: none;
  }
  .cn-input-group > .cn-textarea-control {
    min-height: calc(var(--textarea-min) * var(--cn-unit) - 2px);
  }
  .cn-input-group:has([data-align="block-start"], [data-align="block-end"]) {
    flex-direction: column;
    align-items: stretch;
  }
  .cn-input-group:has([data-align="inline-start"]) .cn-input {
    padding-inline-start: calc(6 * var(--cn-unit));
  }
  .cn-input-group:has([data-align="inline-end"]) .cn-input {
    padding-inline-end: calc(6 * var(--cn-unit));
  }
  .cn-input-group-addon {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    gap: calc(6 * var(--cn-unit));
    cursor: text;
    user-select: none;
    color: var(--cn-text-muted);
  }
  .cn-input-group-addon[data-align="inline-start"] {
    order: -1;
    padding-inline-start: calc(var(--control-inset) * var(--cn-unit) - 1px);
  }
  .cn-input-group-addon[data-align="inline-end"] {
    order: 1;
    padding-inline-end: calc(var(--control-inset) * var(--cn-unit) - 1px);
  }
  .cn-input-group-addon[data-align="block-start"],
  .cn-input-group-addon[data-align="block-end"] {
    width: 100%;
    justify-content: flex-start;
    padding: calc(8 * var(--cn-unit)) calc(var(--control-inset) * var(--cn-unit) - 1px);
  }
  .cn-input-group-addon[data-align="block-start"] {
    order: -1;
  }
  .cn-input-group-addon[data-align="block-end"] {
    order: 1;
  }
  .cn-input-group-addon :where(svg:not([class*="size-"])),
  .cn-input-group-text :where(svg:not([class*="size-"])) {
    width: calc(16 * var(--cn-unit));
    height: calc(16 * var(--cn-unit));
    flex-shrink: 0;
  }
  .cn-input-group-text {
    display: flex;
    align-items: center;
    gap: calc(6 * var(--cn-unit));
    white-space: nowrap;
    color: var(--cn-text-muted);
  }
  /* Actions consume their actual box, including focus clearance, without negative margins. */
  .cn-input-group :is(.cn-button, button, [role="button"]) {
    flex-shrink: 0;
  }
  .cn-input-group > .cn-button {
    margin: calc(3 * var(--cn-unit));
  }
  .cn-input-group-addon:has(button, a, [role="button"]) {
    padding: calc(3 * var(--cn-unit));
  }
  /* Explicit legacy geometry adapter for the protected Date/Time input shells. */
  :is(.rdp-input_surface, .tp-input_surface).cn-input-control {
    height: calc(2.25rem + 2px);
    border-radius: var(--radius);
    font-size: 1.1rem;
    line-height: 1.875rem;
  }
  :is(.rdp-input_surface, .tp-input_surface).cn-input-control[data-size="sm"] {
    height: calc(2rem + 2px);
  }
  :is(.rdp-input_surface, .tp-input_surface).cn-input-control[data-size="lg"] {
    height: calc(2.5rem + 2px);
  }
}
@media (min-width: 40rem) {
  @layer components {
    :is(.rdp-input_surface, .tp-input_surface).cn-input-control {
      font-size: 0.98rem;
    }
    :is(.rdp-input_surface, .tp-input_surface).cn-input-control[data-size="lg"] {
      height: calc(2.125rem + 2px);
    }
  }
}
@media (hover: hover) {
  @layer components {
    .cn-text-shell:not(
        :has(:disabled, [data-disabled], [aria-invalid="true"], [data-invalid])
      ):hover,
    .cn-input-group:not(
        :has(input:disabled, textarea:disabled, [aria-invalid="true"], [data-invalid])
      ):hover {
      border-color: var(--cn-border-hover);
    }
  }
}
@media (max-width: 40rem), (pointer: coarse) {
  @layer components {
    .cn-input:not(:read-only),
    .cn-textarea:not(:read-only) {
      font-size: calc(16 * var(--cn-unit));
      line-height: calc(24 * var(--cn-unit));
    }
  }
}
@media (prefers-reduced-motion: reduce) {
  .cn-text-shell,
  .cn-input-group {
    transition: none;
  }
}
@media (forced-colors: active) {
  .cn-text-shell:has(:focus-visible),
  .cn-input-group:has(input:focus-visible, textarea:focus-visible) {
    outline-color: Highlight;
  }
}
